#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int n, u;
    if (!(std::cin >> n >> u)) return 0;
    std::vector<std::string> grid(n);
    for (auto& row : grid) std::cin >> row;
    auto cost = [&](int r, int c) {
        int painted = (grid[r][c] == '#') + (grid[n-1-r][c] == '#')
                    + (grid[r][n-1-c] == '#') + (grid[n-1-r][n-1-c] == '#');
        return std::min(painted, 4-painted);
    };
    long long total = 0;
    for (int r = 0; r < n/2; ++r)
        for (int c = 0; c < n/2; ++c)
            total += cost(r,c);
    std::cout << total << '\n';
    while (u--) {
        int r, c;
        std::cin >> r >> c;
        --r; --c;
        total -= cost(r,c);
        grid[r][c] = (grid[r][c] == '#' ? '.' : '#');
        total += cost(r,c);
        std::cout << total << '\n';
    }
}
