#include <algorithm>
#include <iostream>
#include <vector>

int minimum_prints(const std::vector<int>& a) {
    int n = static_cast<int>(a.size());
    std::vector<std::vector<int>> lcp(n+1, std::vector<int>(n+1));
    for (int i = n-1; i >= 0; --i)
        for (int j = n-1; j >= 0; --j)
            if (a[i] == a[j]) lcp[i][j] = 1+lcp[i+1][j+1];
    std::vector<std::vector<int>> dp(n, std::vector<int>(n));
    for (int i = 0; i < n; ++i) dp[i][i] = 1;
    for (int length = 2; length <= n; ++length) {
        for (int left = 0; left+length <= n; ++left) {
            int right = left+length-1;
            int best = length;
            for (int split = left; split < right; ++split)
                best = std::min(best, dp[left][split]+dp[split+1][right]);
            for (int period = 1; period <= length/2; ++period)
                if (length % period == 0 && lcp[left][left+period] >= length-period)
                    best = std::min(best, dp[left][left+period-1]);
            dp[left][right] = best;
        }
    }
    return dp[0][n-1];
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int t;
    std::cin >> t;
    while (t--) {
        int n, k;
        std::cin >> n >> k;
        std::vector<int> a(n);
        for (int& x : a) std::cin >> x;
        std::cout << (minimum_prints(a) <= k ? "YES" : "NO") << '\n';
    }
}
